// PROPORTION PIECE: lightweight social cards, no Chromium or Node server.
// JPEGs are generated by the editor and retained in Cloudflare Workers KV.
const SITE='https://southernadd-cmyk.github.io/algoart/';
const ALLOWED_ORIGIN='https://southernadd-cmyk.github.io';
const KEYS=['v','seed','mode','fmt','el','den','cx','neg','phi','rec','spi','ga',
'nest','pen','th','wob','od','op','pr','dry','curve','shape','overlap','rot',
'ln','ci','re','po','ar','pal','cols','sat','bri','paper','grain',
'sheet','material','fit','tissue','watercolor'];
const MODES={field:'Orbital Studies',spiral:'Golden Trajectories',
rects:'Recursive Divisions',burst:'Radiant Systems',network:'Connected Fields',
organic:'Growth Systems',geometric:'Constructed Forms',scribble:'Automatic Marks'};
const MATERIALS={'oil-v1':'Oil Paint','oil-v2':'Oil Paint','oil-v3':'Oil Paint',
'oil-v4':'Oil Paint','oil-v5':'Oil Paint','oil-v6':'Oil Paint','oil-v7':'Oil Paint','watercolour-v2r':'Watercolour',
'watercolour-v2s':'Watercolour','watercolour-v2t':'Watercolour',
'action-v1':'Action Painting','action-v2':'Action Painting','action-v3':'Action Painting'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function decodeToken(raw){
 if(typeof raw!=='string'||raw.length<10||raw.length>1500||
    !/^[A-Za-z0-9_-]+$/.test(raw))return null;
 try{
   const norm=raw.replace(/-/g,'+').replace(/_/g,'/');
   const binary=atob(norm+'='.repeat((4-norm.length%4)%4));
   const check=btoa(binary).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');
   if(check!==raw)return null;
   const bytes=Uint8Array.from(binary,x=>x.charCodeAt(0));
   const parts=new TextDecoder('utf-8',{fatal:true}).decode(bytes).split('\x1f');
   if(parts.length!==KEYS.length||parts.some(x=>x.length>250)||
     !/^[5-9]$/.test(parts[0])||!parts[1]||parts[1].length>80||
     !Object.hasOwn(MODES,parts[2])||
     (parts[3]&&!['portrait','landscape'].includes(parts[3]))||
     parts.some(x=>/[\u0000-\u001e\u007f<>]/u.test(x)))return null;
   return Object.fromEntries(KEYS.map((k,i)=>[k,parts[i]]));
 }catch{return null}
}
function jpegDimensions(bytes){
 const b=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);
 if(bytes.length<10||b.getUint16(0)!==0xffd8||
    b.getUint16(bytes.length-2)!==0xffd9)return null;
 let i=2;
 while(i<bytes.length-9){
   if(bytes[i++]!==0xff)continue;
   const marker=bytes[i++];
   if(marker===0xd8||marker===0xd9||marker===0x01)continue;
   if(i+2>bytes.length)break;
   const n=b.getUint16(i);i+=2;
   if(n<2||i+n-2>bytes.length)break;
   if([0xc0,0xc1,0xc2,0xc3].includes(marker)&&n>=7)
     return {height:b.getUint16(i+1),width:b.getUint16(i+3)};
   i+=n-2;
 }
 return null;
}
const cors={'access-control-allow-origin':ALLOWED_ORIGIN,'vary':'Origin',
'cache-control':'no-store','x-content-type-options':'nosniff'};
const txt=(message,status,headers={})=>new Response(message,{status,headers:{
'content-type':'text/plain; charset=utf-8','cache-control':'no-store',...headers}});
function html(token,data,pv,origin){
 const material=MATERIALS[data.material]||(data.tissue?'Tissue & Graphite':'Marker drawing');
 const title='PROPORTION PIECE — '+MODES[data.mode]+' · '+data.seed;
 const desc='Original '+material+' composition by PROPORTION PIECE. Seed '+data.seed+
   '. Open the exact artwork and explore its golden-ratio structure.';
 // The social image is always a wide card; portrait art is letterboxed inside it.
 const suffix=/^[2-9]$/.test(pv||'')?'&pv='+pv:'';
 const url=origin+'/share?c='+encodeURIComponent(token)+suffix;
 const image=origin+'/share/image?c='+encodeURIComponent(token)+suffix;
 const redirect=SITE+'?c='+encodeURIComponent(token);
 const e=esc;
 return '<!doctype html><html lang="en"><head><meta charset="utf-8">'+
 '<meta name="viewport" content="width=device-width,initial-scale=1">'+
 '<title>'+e(title)+'</title><meta name="description" content="'+e(desc)+'">'+
 '<meta property="og:type" content="website">'+
 '<meta property="og:site_name" content="PROPORTION PIECE">'+
 '<meta property="og:title" content="'+e(title)+'">'+
 '<meta property="og:description" content="'+e(desc)+'">'+
 '<meta property="og:url" content="'+e(url)+'">'+
 '<meta property="og:image" content="'+e(image)+'">'+
 '<meta property="og:image:secure_url" content="'+e(image)+'">'+
 '<meta property="og:image:type" content="image/jpeg">'+
 '<meta property="og:image:width" content="'+1200+'">'+
 '<meta property="og:image:height" content="'+630+'">'+
 '<meta name="twitter:card" content="'+'summary_large_image'+'">'+
 '<meta name="twitter:title" content="'+e(title)+'">'+
 '<meta name="twitter:description" content="'+e(desc)+'">'+
 '<meta name="twitter:image" content="'+e(image)+'">'+
 '</head><body style="background:#f5f0e6;color:#252525;font-family:Georgia,serif;padding:2rem">'+
 '<h1>PROPORTION PIECE</h1><p>Open the exact artwork.</p>'+
 '<a href="'+e(redirect)+'">OPEN ARTWORK</a>'+
 '<script>location.replace('+JSON.stringify(redirect).replace(/</g,'\\u003c')+')</script>'+
 '</body></html>';
}
export default {
 async fetch(request,env){
   const url=new URL(request.url);
   if(url.pathname==='/health')return Response.json({ok:true,service:'proportion-piece-social'});
   if(!['/share','/share/image','/share/preload'].includes(url.pathname))
     return txt('Not found',404);
   if(!env.PREVIEW_KV)return txt('Storage not configured',503);
   const token=url.searchParams.get('c');
   const data=decodeToken(token);
   if(url.pathname==='/share/preload'){
     if(request.headers.get('Origin')!==ALLOWED_ORIGIN)
       return txt('Origin not allowed',403,cors);
     if(request.method==='OPTIONS')return new Response(null,{status:204,headers:{
       ...cors,'access-control-allow-methods':'POST, OPTIONS',
       'access-control-allow-headers':'content-type','access-control-max-age':'600'}});
     if(request.method!=='POST')return txt('Method not allowed',405,{...cors,allow:'POST, OPTIONS'});
     if(!data)return txt('Invalid artwork token',400,cors);
     if(!request.headers.get('content-type')?.toLowerCase().startsWith('application/json'))
       return txt('Expected JSON',415,cors);
     if(Number(request.headers.get('content-length')||0)>420000)
       return txt('Payload too large',413,cors);
     let body;
     try{
       const raw=await request.arrayBuffer();
       if(raw.byteLength>420000)return txt('Payload too large',413,cors);
       body=JSON.parse(new TextDecoder().decode(raw));
     }catch{return txt('Invalid JSON',400,cors)}
     if(typeof body?.jpeg!=='string'||body.jpeg.length>390000||
        !/^[A-Za-z0-9+/]+={0,2}$/.test(body.jpeg))
       return txt('Invalid JPEG',400,cors);
     let bytes;
     try{bytes=Uint8Array.from(atob(body.jpeg),c=>c.charCodeAt(0))}
     catch{return txt('Invalid JPEG',400,cors)}
     const dims=jpegDimensions(bytes);
     if(!dims||dims.width!==1200||dims.height!==630||bytes.length<4000||bytes.length>285000)
       return txt('Invalid JPEG dimensions',400,cors);
     // Identical artwork token is idempotent. No client-provided storage path.
     await env.PREVIEW_KV.put('previews/'+token+'.jpg',bytes.buffer);
     return Response.json({ok:true,bytes:bytes.length},{headers:cors});
   }
   if(!['GET','HEAD'].includes(request.method))
     return txt('Method not allowed',405,{allow:'GET, HEAD'});
   if(!data)return txt('Invalid artwork link',400);
   if(url.pathname==='/share')return new Response(request.method==='HEAD'?null:
     html(token,data,url.searchParams.get('pv'),url.origin),{status:200,headers:{
      'content-type':'text/html; charset=utf-8',
      'cache-control':'public, max-age=1800','x-content-type-options':'nosniff'}});
   const bytes=await env.PREVIEW_KV.get('previews/'+token+'.jpg','arrayBuffer');
   if(!bytes)return txt('Artwork preview not uploaded yet',404);
   return new Response(request.method==='HEAD'?null:bytes,{status:200,headers:{
     'content-type':'image/jpeg','cache-control':'public, max-age=86400, stale-while-revalidate=3600',
     'x-content-type-options':'nosniff'}});
 }
};
export const testing={decodeToken,jpegDimensions,html};


